INSERT INTO job_weekly_plan (job_id, seq, weeks_label, content) VALUES
  (101, 1, '1~2주차', '직무안내 및 담당 브랜드별 특징 안내'),
  (101, 2, '3~4주차', '소셜미디어 및 디지털 캠페인, 프로모션 콘텐츠 기획에 대한 경험 제공'),
  (101, 3, '5~6주차', '소셜미디어 및 디지털 캠페인, 프로모션 콘텐츠 기획에 대한 경험 제공'),
  (101, 4, '7~8주차', '소셜미디어 및 디지털 캠페인, 프로모션 콘텐츠 기획에 대한 경험 제공'),
  (101, 5, '9~10주차', '콘텐츠 제작 협업 및 기획안 수정 보조'),
  (101, 6, '11~12주차', '콘텐츠 제작 협업 및 기획안 수정 보조'),
  (101, 7, '13~14주차', '제안서 작성 및 클라이언트 피드백 수렴 기획안 리워크'),
  (101, 8, '15~16주차', '제안서 작성 및 클라이언트 피드백 수렴 기획안 리워크'),
  (102, 1, '1~2주차', '브랜드 소개 및 마케팅 업무 소개, SNS 매거진 실시간/기획 콘텐츠 제작'),
  (102, 2, '3~4주차', '브랜드 소개 및 마케팅 업무 소개, SNS 매거진 실시간/기획 콘텐츠 제작'),
