  (130, 6, '11~12주차', '방한 외국인들을 위한 콘텐츠 기획 - 주로 텍스트 가이드 형태의 콘텐츠를 제작하고, 이를 위한 기획 수립'),
  (130, 7, '13~14주차', '콘텐츠 제작 - 텍스트 가이드 형태의 콘텐츠 제작 및 이에 맞는 이미지 조사 후 적용'),
  (130, 8, '15~16주차', '제작한 콘텐츠 및 소스 정리 후 마무리'),
  (131, 1, '1~2주차', '1. 기 운영중인 프로그램(등산/유교문화) 프로세스 숙지 및 관련 기초 리서치 수행 2. 기존 데이터 관리 방식 파악 및 기초 데이터 입력'),
  (131, 2, '3~4주차', '1. 프로그램 기획안 작성을 위한 세부 장소(산행 코스, 향교 등) 조사 2. 협력 업체 연락 및 예약 확인 업무'),
  (131, 3, '5~6주차', '1. 프로그램 운영 지원 (현장 체크리스트 작성 및 물품 준비 지원) 2. 주간 업무 진행 데이터 시트 상시 업데이트'),
  (131, 4, '7~8주차', '1. 프로그램 운영 지원 (현장 체크리스트 작성 및 물품 준비 지원) 2. 주간 업무 진행 데이터 시트 상시 업데이트'),
  (131, 5, '9~10주차', '1. 프로그램 운영 지원 (현장 체크리스트 작성 및 물품 준비 지원) 2. 주간 업무 진행 데이터 시트 상시 업데이트'),
  (131, 6, '11~12주차', '1. 프로그램 운영 지원 (현장 체크리스트 작성 및 물품 준비 지원) 2. 주간 업무 진행 데이터 시트 상시 업데이트'),
  (131, 7, '13~14주차', '1. 프로그램 운영 지원 (현장 체크리스트 작성 및 물품 준비 지원) 2. 주간 업무 진행 데이터 시트 상시 업데이트'),
  (131, 8, '15~16주차', '1. 프로그램 운영 결과 피드백 정리 및 데이터 시트 최종 검수 2. 인턴십 수행 업무 최종 보고서 작성 및 문서 인수인계'),
