  (132, 6, '11~12주차', '프로젝트 실무(IP 개발 사업 기획 참여 및 MCN 마케팅 지원)'),
  (132, 7, '13~15주차', '프로젝트 실무(오프라인 행사 현장 운영 참여)'),
  (132, 8, '16주차', '직무수행 평가 및 면담'),
