  (133, 8, '15~16주차', '유망고객 관리(시장 수요반응 결과 정리) 및 업무마무리와 인수인계 보고서 작성'),
  (134, 1, '1주차', '디지털 마케팅 대행사의 역할 및 업계 동향 소개 광고기획자의 자세 등'),
