  (408, 6, NULL, 119, 'educationGoal', '*본 인턴십은 컴퓨터공학 전공 학생들이 실제 산업 현장에서 요구되는 소프트웨어 개발 역량과 문제 해결 능력을 체계적으로 습득하도록 하는 것을 목표로 한다.', 2, '*본 인턴십은 컴퓨터공학 전공 학생들이 실제 산업 현장에서 요구되는 소프트웨어 개발 역량과'),
  (409, 6, NULL, 119, 'jobOverview', '*본 직무는 AI 및 데이터 기반 소프트웨어 개발을 중심으로 다양한 시스템 구축 업무를 수행한다. 주요 업무는 데이터 수집 및 전처리, 간단한 AI 모델 적용 및 테스트, 웹 또는 응용 프로그램 개발 보조, 기존 시스템 유지보수 및 기능 개선 지원 등으로 구성된다. 또한 프로젝트 진행 과정에서 요구사항 분석, 문서 작성, 코드 리뷰 및 테스트 참여를 통해 실제 개발 프로세스를 경험하게 된다.', 2, '*본 직무는 AI 및 데이터 기반 소프트웨어 개발을 중심으로 다양한 시스템 구축 업무를 수행한'),
  (410, 6, NULL, 119, 'majorRequirement', '소프트웨어학과 (1명)', 2, '소프트웨어학과 (1명)'),
