  (541, 8, NULL, 125, 'educationGoal', '*K-뷰티와 연계된 해외 인플루언서 마케팅의 정의와 기초적 실무에 대해 경험', 2, '*K-뷰티와 연계된 해외 인플루언서 마케팅의 정의와 기초적 실무에 대해 경험'),
  (542, 8, NULL, 125, 'jobOverview', '바이럴 마케팅 실무를 경험하며 시장조사, 콘텐츠 기획, 인플루언서 마케팅 운영 역량을 습득하고, 데이터 분석을 통한 마케팅 인사이트 도출 능력을 함양하는 것을 목표로 함', 2, '바이럴 마케팅 실무를 경험하며 시장조사, 콘텐츠 기획, 인플루언서 마케팅 운영 역량을 습득하고,'),
