  (560, 8, NULL, 126, 'educationGoal', '온라인 커머스 운영 및 MD 실무를 경험하며 상품 분석, 시장조사, 데이터 활용 능력을 습득하고, 판매 채널별 전략 및 프로모션 기획에 대한 이해를 높이는 것을 목표로 한다.', 3, '온라인 커머스 운영 및 MD 실무를 경험하며 상품 분석, 시장조사, 데이터 활용 능력을 습득하고,'),
  (561, 8, NULL, 126, 'jobOverview', '실습생은 MD 담당자의 지도 아래 상품 운영 지원, 시장 및 경쟁사 조사, 판매 데이터 분석, 프로모션 운영 지원 등의 업무를 수행한다. 또한 상품기획 프로세스, 매출 분석 방법, 온라인 커머스 운영 전략 등에 대한 직무교육을 병행하며 데이터 기반의 의사결정 과정을 경험한다.', 3, '실습생은 MD 담당자의 지도 아래 상품 운영 지원, 시장 및 경쟁사 조사, 판매 데이터 분석, 프로모션'),
