INSERT INTO field_evidence (id, source_document_id, institution_id, job_id, field_key, raw_value, page, quote) VALUES
  (601, 8, NULL, 128, 'jobOverview', '온·오프라인 채널의 운영 효율성을 높이기 위해 판매, 물류, 마케팅 핵심 데이터를 일관성 있게 취합하고 분석하는 ''데이터 중심의 마케팅 지원'' 직무입니다. 쿠팡 등 온라인 채널의 트래픽·광고 데이터 분석과 오프라인·폐쇄몰 채널의 발주/매출 데이터 기입을 연계 수행하며, 브랜드 인지도 확산을 위한 글로벌 바이럴 마케팅(체험단)의 섭외, 운영 및 모니터링 실무를 담당합니다.', 5, '온·오프라인 채널의 운영 효율성을 높이기 위해 판매, 물류, 마케팅 핵심 데이터를 일관성 있게'),
