  (621, 8, NULL, 129, 'jobOverview', '인플루언서 체험단 운영을 통해 국내 시장 내 브랜드 인지도와 판매 전환을 확대를 위한 인플루언서를 섭외 및 제품 발송, 콘텐츠 업로드 일정 및 결과를 관리하며, 콘텐츠 성과를 분석하여 운영을 개선하는 업무를 수행', 7, '인플루언서 체험단 운영을 통해 국내 시장 내 브랜드 인지도와 판매 전환을 확대를 위한'),
