  (666, 9, NULL, 131, 'jobOverview', '1. 운영 중인 등산 및 유교 문화 프로그램 기획을 위한 기초 자료 조사 및 계획안 작성 지원 2. 프로그램 운영 일정표 관리 및 참가자 문의 응대 보조 3. 협력 업체(장소, 물품 등) 컨택 업무 지원 및 필요 서류 준비 4. 프로그램 관련 데이터 시트(참가자 명단, 예산 등) 구축 및 업데이트 관리 5. 행사 후 결과 보고를 위한 데이터 정리 및 통계 보조', 4, '1. 운영 중인 등산 및 유교 문화 프로그램 기획을 위한 기초 자료 조사 및 계획안 작성 지원'),
