  (794, 14, NULL, 136, 'educationGoal', 'AI 학습데이터 구축 프로젝트의 전 과정을 이해하고, 데이터 수집, 정제, 라벨링, 품질검수 및 운영 지원 업무를 수행함으로써 AI 데이터 구축 실무 역량과 데이터 품질관리 능력을 습득한다. 또한 실제 프로젝트 수행 과정에서 문제 해결 능력, 협업 능력, 문서화 능력 및 AI 데이터 구축 프로세스에 대한 이해를 향상시키는 것을 목표로 한다.', 2, 'AI 학습데이터 구축 프로젝트의 전 과정을 이해하고, 데이터 수집, 정제, 라벨링, 품질검수 및 운영 지원 업무를'),
  (795, 14, NULL, 136, 'jobOverview', 'AI 학습데이터 구축 프로젝트에서 필요한 데이터 수집, 정제, 라벨링 및 품질 검수(QA) 업무를 수행하여 AI 서비스 개발에 활용되는 학습데이터를 구축하고 품질을 확보한다. 업무는 프로젝트별 작업 가이드와 품질 기준에 따라 담당자의 지도와 피드백을 받아 수행하며, 데이터 관리, 결과물 정리, 작업 현황 관리 등 프로젝트 운영에 필요한 실무 지원 업무까지 담당한다.', 2, 'AI 학습데이터 구축 프로젝트에서 필요한 데이터 수집, 정제, 라벨링 및 품질 검수(QA) 업무를 수행하여 AI'),
  (796, 14, NULL, 136, 'majorRequirement', '이공계열 / 2명', 2, '이공계열 / 2명'),
  (797, 14, NULL, 136, 'headcount', '2명', 2, '이공계열 / 2명'),
  (798, 14, NULL, 136, 'gradeRequirement', '학년 무관', 2, '학년 무관'),
  (799, 14, NULL, 136, 'gpaRequirement', '학점 무관', 2, '학점 무관'),
  (800, 14, NULL, 136, 'competencies', '작업 가이드와 세부 기준을 정확하게 이해하고 준수할 수 있는 역량이 필요합니다. 꼼꼼한 업무 수행 능력과 기본적인 컴퓨터 활용 능력, 생성형 AI(ChatGPT 등)를 활용하여 업무를 수행하고 피드백을 반영할 수 있는 역량을 요구합니다.', 2, '작업 가이드와 세부 기준을 정확하게 이해하고 준수할 수 있는 역량이 필요합니다. 꼼꼼한 업무');
