  (820, 15, NULL, 137, 'educationGoal', '* 중국 패션 시장 및 글로벌 Business Development(BD) 실무를 경험하며 시장조사, 비즈니스 커뮤니케이션 역량을 향상시켜 실무형 인재로 성장하는 것을 목표로 한다.', 2, '중국 패션 시장 및 글로벌 Business Development(BD) 실무를 경험하며 시장조사, 비즈니스 커뮤니케이션'),
  (821, 15, NULL, 137, 'jobOverview', '* 실습생은 브랜드의 중국 시장 진출을 위하여 중국 시장 및 사업 리서치를 진행하며, toomuchtax 브랜드와 관련된 업무를 진행한다. * 중국 패션 플랫폼(Douyin, Xiaohongshu), 현지 셀러, KOL, 유통사 등 다양한 시장 참여자를 분석하고, 협업 가능성이 있는 파트너를 선정하여 다양한 채널을 활용하여 컨택하며 미팅 일정 조율 및 커뮤니케이션을 담당한다. * 시장조사부터 잠재 파트너 발굴, 비즈니스 커뮤니케이션, 결과 보고 및 개선 제안까지의 과정을 포함하며, 현업 담당자의 피드백을 통해 단계적으로 실무 역량을 향상시킨다.', 2, '실습생은 브랜드의 중국 시장 진출을 위하여 중국 시장 및 사업 리서치를 진행하며, toomuchtax 브랜드와'),
  (822, 15, NULL, 137, 'majorRequirement', '경영계열, 중국 관련 학과(글로벌비즈니스어학부) / 인원: 1명', 3, '경영계열, 중국 관련 학과(글로벌비즈니스어학부) / 인원: 1명'),
