-- review_alert 12행
INSERT INTO review_alert (id, institution_id, job_id, kind, field_key, description, source_document_id, page_a, quote_a, page_b, quote_b) VALUES
  (1, 2, NULL, 'DOC_INCONSISTENCY', NULL, '교육목표의 대상 전공과 달리 학생요건 전공 칸의 전공 구성이 쪽마다 다르다: 2~3쪽 직무에는 영화영상학과가 포함되고 4쪽 직무에는 빠져 있다(서로 다른 직무라 불일치가 아닐 수 있음).', 2, 3, '무대패션전공, 광고홍보콘텐츠학과, 영화영상학과, 경영학부', 4, '무대패션전공, 광고홍보콘텐츠학과, 경영학부 ( )'),
  (2, 4, 115, 'LIST_MISMATCH', 'period', '실습기간: 참여기관 리스트는 2026-09-01~2026-12-12, 운영계획서는 2026-09-01~2025-12-12', 4, 2, '2026년 9월 1일 ~ 2025년 12월 12일', NULL, NULL),
  (3, 4, 116, 'LIST_MISMATCH', 'period', '실습기간: 참여기관 리스트는 2026-09-01~2026-12-12, 운영계획서는 2026-09-01~2025-12-12', 4, 4, '2026년 9월 1일 ~ 2025년 12월 12일', NULL, NULL),
  (4, 4, 116, 'LIST_MISMATCH', 'majorRequirement', '선호 전공: 참여기관 리스트는 인문, 사회계열, 운영계획서는 전공 무관', 4, 4, '전공무관 3명', NULL, NULL),
  (5, 6, NULL, 'DOC_INCONSISTENCY', NULL, '교육목표의 대상 전공은 컴퓨터공학인데, 학생요건의 전공은 소프트웨어학과로 서로 다르다.', 6, 2, '*본 인턴십은 컴퓨터공학 전공 학생들이 실제 산업 현장에서 요구되는 소프트웨어 개발 역량과', 2, '소프트웨어학과 (1명)'),
  (6, 9, NULL, 'DOC_INCONSISTENCY', NULL, '기관현황의 사업의 종류(종목)는 ''응용소프트웨어 개발 및 공급업''인데 사전 서면점검서의 종목은 ''소프트웨어 개발 및 공급업''으로 다르게 적혀 있다.', 9, 1, '응용소프트웨어 개발 및 공급업', 6, '소프트웨어 개발 및 공급업'),
  (7, 9, NULL, 'DOC_INCONSISTENCY', NULL, '1~2쪽 직무의 운영/지도계획은 16주차(15~16주차)까지 있으나 실습기간은 2026년 9월 1일~12월 12일로 약 15주여서 계획 주차와 기간이 맞지 않는다.', 9, 2, '2026년 9월 1일 ~ 2026년 12월 12일', 3, '* 15~16주차: 제작한 콘텐츠 및 소스 정리 후 마무리'),
  (8, 9, 130, 'LIST_MISMATCH', 'majorRequirement', '선호 전공: 참여기관 리스트는 글로벌비즈니스어학부, 경영학부, 광고홍보콘텐츠학과, 운영계획서는 전공 무관', 9, 3, '무관 (1인)', NULL, NULL),
  (9, 9, 131, 'LIST_MISMATCH', 'majorRequirement', '선호 전공: 참여기관 리스트는 글로벌비즈니스어학부, 경영학부, 광고홍보콘텐츠학과, 운영계획서는 전공 무관', 9, 5, '무관 (1인)', NULL, NULL),
  (10, 10, NULL, 'DOC_INCONSISTENCY', NULL, '사업의 종류(업태·종목)가 1쪽 기관현황에는 ''정보통신업'', ''광고영화 및 비디오물 제작업''으로, 사전 서면점검서에는 ''정보통신업 외'', ''광고 영화 및 비디오물 제작업 외''로 다르게 적혀 있다.', 10, 1, '광고영화 및 비디오물 제작업', 3, '광고 영화 및 비디오물 제작업 외'),
  (11, 12, NULL, 'DOC_INCONSISTENCY', NULL, '운영계획서 1쪽의 한국표준산업분류코드(743002)와 사전 서면점검서 3쪽의 한국표준산업분류코드(71310)가 다르다.', 12, 1, '한국표준산업분류코드 743002', 3, '한국표준산업분류코드 71310'),
  (12, 16, 138, 'LIST_MISMATCH', 'stipendAmount', '실습지원비: 참여기관 리스트는 1,617,660원, 운영계획서는 1,700,000원', 16, 2, '[1,700,000]원', NULL, NULL);

-- testimonial 17행
INSERT INTO testimonial (id, source_document_id, institution_id, team_text, activities, page) VALUES
  (1, 19, 4, '강의제작팀', ARRAY['촬영자료(PPT) 제작 및 검수', '강의 검수', '학습자료 제작', '샘플 강의 / 홍보영상 선정', '목차 작업 / 오픈 작업', '강의의 CS 관련 작업이나 수정 작업 등 기타 작업', '공모전 참여']::text[], 1),
  (2, 19, 3, 'OL디자인팀', ARRAY['디자이너별 작업 지시서 분류', '샘플 관리', '작업 지시서 작성', '의상 제작', '부자재 셀렉', '업체에 생산 요청', '수정사항 정리 및 1차 품평 진행']::text[], 3),
  (3, 19, 7, '마케팅&제품개발팀', ARRAY['영상 기획 및 제작', '인스타그램 팔로워와의 소통 업무', '브랜드 계정 재활성', '프로모션& 광고 기획', '인플루언서 마케팅 진행', '스킨케어 라인 신제품 개발']::text[], 9),
  (4, 19, 11, '사업부', ARRAY['결과보고서, 수요기술조사서 작성 후 업로드', 'DBN, 델타텍코리아 웹사이트 관리', '행사 및 프로젝트 미팅 참가 시 통역 및 회의록 작성', '매주 과학기사 5개 번역', 'EEN 기술 프로파일 피드백 및 등록', '국내/외 기업과 유선 및 이메일 연락사무', '글로벌화 프로젝트 지원 업무']::text[], 11),
  (5, 20, 9, '콘텐츠팀', ARRAY['SNS 게시글 콘텐츠 기획 및 자료 수집', 'SNS 게시글 광고 게재 및 성과 지표화 업무', '수치를 바탕으로 효과적인 게시글 작성법 습득', '콘텐츠 기획 및 작성, 디자인 툴 실전 적용', '애플리케이션에 게재되는 배너 및 홍보물 디자인 제작']::text[], 7),
  (6, 20, 11, '사업부', ARRAY['기술 제품 이해 및 시장 동향 조사', '시장 조사 데이터를 DB 형태로 정리', '산업 Value-Chain 이해 및 목표 고객 선정', 'Sales Pipeline 작성 및 잠재 고객 목록 작성', '무역 거래 문서 작성', '잠재 고객 타색 및 목록 작성', '해외 수요 기업 발굴', '기술 판촉 활동 결과 정리', '보고서 기반하여 기술 판촉 성과와 개선 방향 도출']::text[], 13),
  (7, 20, 7, '마케팅팀', ARRAY['서포터즈 관리 및 선발', 'SNS 계정 관리 및 업로드', '인플루언서 시딩 리스트업', '콘텐츠 기획 및 제작', '국내외 광고 제작', '팝업 이벤트 기획: 팝업 컨셉 및 슬로건 기획', '팝업 서포터즈', '외부 미팅 참여 및 거래처 이미지 업로드']::text[], 15),
  (8, 20, 17, '안전진단팀', ARRAY['어린이집 건축물 안전진단 후 결함 위치 도면 그리기 및 결과보고서 작성', 'OOO 건축물 외관 그리기 작업', '건축물 외관 조사 부록 정리, 결과표 정리', '건축물 보수작업에 필요한 재료 조사', 'MIDAS 프로그램 배우고 활용하기', '그 외 자료 및 보고서 정리 등']::text[], 19),
  (9, 21, 10, '마케팅솔루션 2팀', ARRAY['전반적인 사내 업무 프로세스 파악 (견적서, 예산서, 정산서 작성 및 제안서, 계약서 작성)', '사내 아웃바운드 진행', '미쉐린 코리아 기업 행사 운영 기획서 작성', '2025 렛츠런파크 어린이 놀자 페스티벌, 브레드이발소/엄마까투리 싱어롱쇼 계약 담당', '태백시 날아라 새들아, 슈퍼윙스 퍼레이드 계약 담당', '천안 흥타령 춤축제, 샌드박스 계약 진행중']::text[], 5),
  (10, 21, 7, '물류팀', ARRAY['내부재고 관리, 물류창고 재고, 이동중인 재고, 해외재고 관리', '수출 준비 참여', '인터넷 판매건 출고시키기', '물류비 절감 방안 생각', '물류비 기록', '해외로 보내지는 물류비들이 오차가 없는지 비교하기 위해', '모든 물류비를 기록하고 영수증과 비교함']::text[], 9),
  (11, 21, 9, '콘텐츠팀', ARRAY['저는 매주 작성하는 게시글 사진 사용 허가와 SNS 카드뉴스 제작을 담당했습니다. 매주 화요일, 금요일 두 번의 게시를 위해 회의를 통해 게시글 주제를 선정하고 작성된 글의 초안에 어울리는 사진을 데스크 리서치를 통해 허가받아 업로드 했습니다. 게시글 작성 이후에는 인스타그램과 페이스북에 제작할 카드뉴스를 제작했습니다. 디자인 툴을 이용해 알맞은 문구와 사진을 삽입해 제작을 마쳤습니다. 이후, 인스타그램과 페이스북에 업로드해 광고 집행을 통한 반응과 인사이트 통계도 확인했습니다.']::text[], 11),
  (12, 22, 1, '광고사업부', ARRAY['투썸플레이스 인스타그램 콘텐츠 기획 및 운영', '광고 소재 기획 및 발행', '광고 성과 모니터링, 효과적인 콘텐츠 전략 제안', '광고 소재 기획 및 집행']::text[], 1),
  (13, 22, 3, 'OL디자인실', ARRAY['디자인 기획부터 출고까지 전 과정 보조', '업무 우선순위 설정', '디자인 기획, 샘플링, 자재 수급, 출고 사이클 관찰', '공정상 오류나 데드라인 압박 등 다양한 변수 대처 및 프로젝트 지원']::text[], 5),
  (14, 22, 7, '마케팅팀', ARRAY['신제품 기획과 마케팅 업무 전반 보조', '시장 및 경쟁 제품 분석을 통한 신제품 기획 지원', '제품 정보 정리 및 자료 리서치 임무', '콘텐츠 기획 보조']::text[], 9),
  (15, 22, 10, '마케팅솔루션팀', ARRAY['굿즈 및 팝업스토어, 축제디자인', '촬영 및 사업 보조', '행사 및 팝업스토어 운영', '버스킹 운영 및 공연 현장 보조']::text[], 11),
  (16, 22, 11, '사업', ARRAY['거래 제의서, 피치덱 등 영업 문서 작성 및 발송', '전시회/박람회 참가 및 해외 기업 B2B 미팅', '관심 기업 대상 화상회의 알선 및 통역', '기술 실증 데이터 클러스터 분석 및 보고서 작성']::text[], 17),
  (17, 22, 9, '콘텐츠팀', ARRAY['외국인들을 위한 콘텐츠 제작 보조', '행사 진행을 위한 사무 보조', '정기 콘텐츠 업로드를 위한 제작 보조', '신규 서비스 런칭/진행을 위한 업무 보조']::text[], 19);

